int maxDistance(vector<int>& arr) {
    int n=arr.size();
    vector<int> lmin(n), rmax(n);
    lmin[0]=arr[0];
    for (int i=1;i<n;i++) lmin[i]=min(lmin[i-1],arr[i]);
    rmax[n-1]=arr[n-1];
    for (int j=n-2;j>=0;j--) rmax[j]=max(rmax[j+1],arr[j]);
    int i=0, j=0, ans=0;
    while (i<n && j<n) {
        if (lmin[i]<=rmax[j]) { ans=max(ans,j-i); j++; }
        else i++;
    }
    return ans;
}
// Time: O(N)  Space: O(N)

int maxScore(vector<int>& c, int k) {
    int n=c.size(), total=0;
    for (int i=0;i<k;i++) total+=c[i];
    int cur=total;
    for (int i=1;i<=k;i++) {
        cur += c[n-i] - c[k-i];
        total = max(total, cur);
    }
    return total;
}
