// O(log N) space — use already set 'next' pointers as "free" traversal
Node* connect(Node* root) {
    if(!root) return nullptr;
    Node* leftmost=root;
    while(leftmost->left){
        Node* head=leftmost;
        while(head){
            head->left->next=head->right;
            if(head->next) head->right->next=head->next->left;
            head=head->next;
        }
        leftmost=leftmost->left;
    }
    return root;
}
// Time: O(N)  Space: O(1) — the interviewer's expected O(log N) approach

