long long diceThrow(int D, int F, int S){
    // dp[i][j] = ways to get sum j using i dice
    vector<vector<long long>> dp(D+1,vector<long long>(S+1,0));
    dp[0][0]=1;
    for(int d=1;d<=D;d++)
        for(int s=d;s<=S;s++)
            for(int f=1;f<=F && f<=s;f++)
                dp[d][s]+=dp[d-1][s-f];
    return dp[D][S];
}
// Time: O(D*S*F)  Space: O(D*S)

