class LRUCache {
    int cap;
    list<pair<int,int>> dll;  // {key,val} — front=most recent
    unordered_map<int,list<pair<int,int>>::iterator> mp;
public:
    LRUCache(int c):cap(c){}
    int get(int key){
        if(!mp.count(key)) return -1;
        dll.splice(dll.begin(),dll,mp[key]);
        return mp[key]->second;
    }
    void put(int key, int val){
        if(mp.count(key)) dll.erase(mp[key]);
        else if(dll.size()==cap){ mp.erase(dll.back().first); dll.pop_back(); }
        dll.push_front({key,val}); mp[key]=dll.begin();
    }
};
// get/put: O(1)  Space: O(cap)

