int findUnsortedSubarray(vector<int>& nums){
    int n=nums.size(), lo=n, hi=-1;
    int mn=INT_MAX, mx=INT_MIN;
    for(int i=0;i<n;i++){
        mx=max(mx,nums[i]);
        if(nums[i]<mx) hi=i;
    }
    for(int i=n-1;i>=0;i--){
        mn=min(mn,nums[i]);
        if(nums[i]>mn) lo=i;
    }
    return hi==-1 ? 0 : hi-lo+1;
}
