int totalJumps(vector<int>& walls, int H, int L){
    int jumps=0, curHeight=0;
    for(int w:walls){
        while(curHeight<w){
            curHeight+=H;  // jump
            jumps++;
            if(curHeight<w) curHeight-=L; // slip (only if not cleared)
        }
        curHeight=0; // reset for next wall
    }
    return jumps;
}
